use kimo_core::color::matching::*;
fn mm(a:[[f64;3];3],b:[[f64;3];3])->[[f64;3];3]{std::array::from_fn(|i|std::array::from_fn(|j|(0..3).map(|k|a[i][k]*b[k][j]).sum()))}
#[test]fn lab_roundtrip(){for i in 0..1000{let c=[(i%17) as f64/16.,(i%31) as f64/30.,(i%43) as f64/42.];let d=from_lab(to_lab(c));for j in 0..3{assert!((c[j]-d[j]).abs()<2e-12)}}}
#[test]fn full_covariance_transfer(){let a=Stats{mean:[0.;3],cov:[[0.1,0.02,0.01],[0.02,0.2,0.03],[0.01,0.03,0.15]],count:100};let b=Stats{mean:[0.;3],cov:[[0.2,0.04,-0.01],[0.04,0.1,0.02],[-0.01,0.02,0.05]],count:100};let m=transport(&a,&b,1e-8).unwrap();let mut reg=a.cov;for i in 0..3{reg[i][i]+=1e-8}let pred=mm(mm(m,reg),m);for i in 0..3{for j in 0..3{assert!((pred[i][j]-b.cov[i][j]-if i==j{1e-8}else{0.}).abs()<1e-10)}}}
#[test]fn flat_regularized_and_hostile(){let a=Stats{mean:[0.;3],cov:[[0.;3];3],count:100};let m=transport(&a,&a,1e-4).unwrap();for i in 0..3{for j in 0..3{assert!((m[i][j]-if i==j{1.}else{0.}).abs()<1e-12)}}assert!(transport(&a,&a,0.).is_err());assert!(transport(&a,&a,f64::NAN).is_err());}
#[test]fn transparent_and_invalid_region_rejected(){let f=kimo_core::effects::Frame{w:4,h:4,d:vec![0.;64]};assert!(statistics(&f,None).is_err());assert!(statistics(&f,Some([-0.1,0.,1.,1.])).is_err());assert!(statistics(&f,Some([0.,0.,2.,1.])).is_err());}
#[test]fn stats_shape_and_invalid_alpha(){for f in [kimo_core::effects::Frame{w:4,h:4,d:vec![0.;4]},kimo_core::effects::Frame{w:usize::MAX,h:2,d:vec![]}]{assert!(statistics(&f,None).is_err());}for a in [f32::NAN,f32::INFINITY,1.01,-1.]{let f=kimo_core::effects::Frame{w:4,h:4,d:(0..16).flat_map(|_|[0.1,0.2,0.3,a]).collect()};assert!(statistics(&f,None).is_err());}}
#[test]fn transport_source_evidence_invalid(){let good=Stats{mean:[0.;3],cov:[[1.,0.,0.],[0.,1.,0.],[0.,0.,1.]],count:100};for bad in [Stats{mean:[f64::NAN,0.,0.],..good.clone()},Stats{count:0,..good.clone()},Stats{cov:[[-1.,0.,0.],[0.,1.,0.],[0.,0.,1.]],..good.clone()},Stats{cov:[[1.,1.,0.],[0.,1.,0.],[0.,0.,1.]],..good.clone()}]{assert!(transport(&bad,&good,1e-4).is_err());}}
#[test]fn indefinite_covariance_rejected_not_silently_regularized(){let a=Stats{mean:[0.;3],cov:[[1.,2.,0.],[2.,1.,0.],[0.,0.,1.]],count:100};let b=Stats{mean:[0.;3],cov:[[1.,0.,0.],[0.,1.,0.],[0.,0.,1.]],count:100};assert!(transport(&a,&b,0.1).is_err());let a=Stats{cov:[[1.,-0.9,-0.9],[-0.9,1.,-0.9],[-0.9,-0.9,1.]],..a};assert!(transport(&a,&b,0.1).is_err());let flat=Stats{cov:[[0.;3];3],..b};assert!(transport(&flat,&flat,0.001).is_ok());}
#[test]fn lab_effect_rejects_invalid_alpha(){use kimo_core::{effects::{Frame,Params},color::matching};for alpha in [-0.1,1.01]{let mut f=Frame{w:1,h:1,d:vec![0.1,0.2,0.3,alpha]};let before=f.d.clone();assert!(matching::apply(&Params::new(),&mut f,0.).is_err());assert_eq!(f.d,before);}}

#[test]fn lab_effect_rejects_nonfinite_controls_before_mutation(){use kimo_core::{effects::{Frame,Params},keyframe::Prop,color::matching};for key in ["strength","gamut_compress"]{for value in [f64::NAN,f64::INFINITY,f64::NEG_INFINITY]{let mut p=Params::new();p.insert(key.into(),Prop::new(value));let mut f=Frame{w:1,h:1,d:vec![0.1,0.2,0.3,1.]};let before=f.d.clone();assert!(matching::apply(&p,&mut f,0.).is_err());assert_eq!(f.d,before);}}}
